    /// Asset path of the secondary layer, for the duotone icons.
    pub fn duo_path(self) -> Option<SharedString> {
        Some(SharedString::new_static(match self {
            Self::DuoDatabase => "icons/duo-database.duo.svg",
            Self::DuoKey => "icons/duo-key.duo.svg",
            Self::DuoServer => "icons/duo-server.duo.svg",
            Self::DuoTable => "icons/duo-table.duo.svg",
            Self::DuoTerminal => "icons/duo-terminal.duo.svg",
            // The panel toggles shade the region they open, which is the
            // second layer; drawn `.flat()` they are the same outline with
            // nothing in it, and that is exactly what "closed" should look
            // like.
            Self::PanelBottom => "icons/panel-bottom.duo.svg",
            Self::PanelLeft => "icons/panel-left.duo.svg",
            Self::PanelRight => "icons/panel-right.duo.svg",
            _ => return None,
        }))
    }

    /// Whether this icon has a second layer.
    pub fn has_duo_layer(self) -> bool {
        self.duo_path().is_some()
    }

